# WLR/pages/ui.R  --  The WLR user interface: the folders, the Standard pages, the set-up flow pages and ui.
# Sourced by app.R at the top level (local = TRUE); the Workbench (workbench/wb_wlr.R) reuses these pages.

if (dir.exists(file.path(APP_DIR, "docs"))) addResourcePath("docs", file.path(APP_DIR, "docs"))
# The folders (Home in the Standard interface, Import data in the Workbench).
std_folders <- function() fluidRow(column(7, div(class = "panel-x", h3("Folders"),
          textAreaInput("raw_dirs", "Data folders, one per line (each holds 2025/, 2024/ ... and baro/2025/ ...)", paste(SETTINGS$raw_dirs, collapse = "\n"), rows = 2, width = "100%"),
          ovid_browse_button("raw_dirs"), uiOutput("raw_check"),
          textInput("metadata_dir", "Metadata folder, optional (the newest .xlsx in it is the WL_Metadata workbook; or use the deployment sheet)", SETTINGS$metadata_dir, width = "100%"), ovid_browse_button("metadata_dir"), uiOutput("meta_check"),
          textInput("dgps_dir", "dGPS folder (survey exports, .csv)", SETTINGS$dgps_dir, width = "100%"), ovid_browse_button("dgps_dir"),
          textInput("project_dir", "Project folder (set-up tables and output are kept here)", SETTINGS$project_dir, width = "100%"), ovid_browse_button("project_dir"),
          textInput("years", "Years to process (blank = every year with data), e.g. 2024, 2025", paste(SETTINGS$years, collapse = ", "), width = "100%"))),
          column(5, div(class = "panel-x flat", h3("How the folders are read"),
            tags$ul(class = "dim", tags$li("A year folder (2025) holds that year's water level and conductivity downloads."),
                    tags$li("baro/2025 holds that year's barologgers. A logger typed Baro in the workbook counts as one wherever it is."),
                    tags$li(".hobo files are paired with their HOBOware CSV exports; .xle files with their Solinst CSVs."),
                    tags$li("The same serial in several years is stitched into one record, then split into deployments by the workbook's visit dates.")))))
# The rail's stages fold, only the stage of the page shown open (www/rail_stages.js), so the rail fits the screen.
wlr_rail_css <- paste(".wl-stage-head{cursor:pointer;user-select:none}.wl-stage-head:hover{color:var(--acc)}",
  ".wl-stage-chev::after{content:'\\203A';display:inline-block;font-size:12px;line-height:1;transition:transform .15s}",
  ".wl-stage-head[aria-expanded=true] .wl-stage-chev::after{transform:rotate(90deg)}.wl-stage-body.wl-shut{display:none}",
  ".wl-stage-body{display:flex;flex-direction:column;gap:inherit}")
std_css <- function() paste(nord_css, legible_css(good = "--aqua"), wlr_rail_css)
std_head <- function() tagList(tags$script(src = "rail_stages.js"), if (exists("useBusyIndicators", asNamespace("shiny"))) shiny::useBusyIndicators(spinners = FALSE, pulse = TRUE),
                 if (VIEWER) tags$script(HTML("document.addEventListener('DOMContentLoaded',function(){document.documentElement.classList.add('viewer')});")))
# The Standard pages: the tools and section labels for ovid_page(), in rail order. The Workbench shows the same pages in
# its own frame (workbench/wb_wlr.R); there sources = FALSE leaves the folders off Home, as its Import view holds them.
std_pages <- function(sources = TRUE) list(
    ovid_tool("Home", icon = "house",
      h2("Water level hub"), p(class = "lede", "Every HOBO and Solinst download in one place: stitched by serial across years, split into deployments from the metadata workbook, compensated with the barologger of each site's group, turned into metres of water above the sensor and water elevations, and checked. Raw files are never changed."),
      uiOutput("stats"),
      h4("Deployments"), p(class = "dim", "Click a row to open it in Plot and explore."), DTOutput("home_dep"),
      h4("What each logger covers"),
      div(class = "scrollbox", plotOutput("timeline", height = "auto")),
      if (!VIEWER) fluidRow(
        column(6, div(class = "d-cardx", h3("Next time"), p("Put the new downloads from the field into the year's folder (and baro/<year> for barologgers) and press ", tags$b("Run pipeline"),
            ". Loggers whose files and set-up have not changed are reused; everything set up here is used again."),
          tags$a(href = "#", `data-ovid-go` = "Files", "Bring in new files \u203a"))),
        column(6, div(class = "d-cardx", h3("Recent changes"), uiOutput("saved_hist")))),
      if (!VIEWER && sources) p(class = "dim", "The data folders are on ", tags$a(href = "#", `data-ovid-go` = "Project", "1 Project"), "."),
      tags$details(class = "editor-only", tags$summary("Log of the last run"), uiOutput("log")),
      div(class = "foot", "Output is written to the project folder: output/sites (one CSV per deployment), output/baro, output/plots, output/audit (audit trail and metadata).")),

    "View",
    ovid_tool("Plot and explore", value = "Explore", icon = "chart-line",
      page_head("Plot and explore", "One site at a time, for one deployment or every year together; or several sites, or several years of one site, on one axis. On a single site, drag across the plot to select a stretch (drag up a panel's value axis to narrow it to a band of values); the bar above it zooms in, removes the values or the points in the band, moves the deployment start or end, or marks the stretch out of the water."),
      tabsetPanel(id = "ex_tab",
        tabPanel("One site",
          ovid_controls(
            selectInput("ex_site", "Site", choices = NULL, width = "100%"),
            selectInput("ex_dep", "Deployment", choices = NULL, width = "100%"),
            tagAppendAttributes(selectizeInput("ex_params", "Show", choices = param_choices, selected = c("depth_m", "temp_c", "baro_kpa"), multiple = TRUE, width = "100%"), class = "d-wide"),
            ovid_split_toggle("ex_split", "Plot and table"),
            more = tagList(checkboxInput("ex_marks", "Shade removals and out-of-water", TRUE), checkboxInput("ex_meas", "Show manual measurements", TRUE),
                           div(class = "btnrow", downloadButton("ex_dl", "Export data (CSV)"))),
            more_label = "Plot options and export"),
          ovid_split("ex_split", width = "40%",
            tagList(ts_viewbar(), ts_view("ex_tsv", 190)),
            tagList(h4("Summary"), tableOutput("ex_stats"), h4("Flags on this record"), DTOutput("ex_flags")))),
        tabPanel("Compare sites",
          ovid_controls(
            tagAppendAttributes(selectizeInput("cs_sites", "Sites", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "Pick two or more")), class = "d-wide"),
            selectInput("cs_param", "Value", param_choices[param_choices %in% c("depth_m", "elev_m", "dtw_m", "temp_c", "spc_uscm", "baro_kpa", "pres_kpa")], width = "100%"),
            selectInput("cs_res", "Show as", c("Daily mean" = "day", "Hourly mean" = "hour", "Every record" = "raw"), width = "100%"),
            ovid_split_toggle("cs_split", "Plot and table"),
            more = tagList(selectInput("cs_mode", "Scale", c("Values" = "value", "Difference from each site's median" = "anomaly"), width = "100%"),
                           suppressWarnings(dateRangeInput("cs_dates", "Period (blank = everything)", start = NA, end = NA, width = "100%")),
                           div(class = "btnrow", downloadButton("cs_png", "Export plot (PNG)"), downloadButton("cs_dl", "Export these values (CSV)"))),
            more_label = "Scale, period and export"),
          uiOutput("cs_hint"),
          ovid_split("cs_split", width = "34%",
            ovid_focus(plotOutput("cs_plot", height = "560px")),
            tagList(h4("Summary by site"), tableOutput("cs_stats")))),
        tabPanel("Compare years",
          ovid_controls(
            selectInput("cy_site", "Site", choices = NULL, width = "100%"),
            selectInput("cy_param", "Value", param_choices[param_choices %in% c("depth_m", "elev_m", "dtw_m", "temp_c", "spc_uscm", "baro_kpa")], width = "100%"),
            selectInput("cy_res", "Show as", c("Daily mean" = "day", "Hourly mean" = "hour", "Every record" = "raw"), width = "100%"),
            ovid_split_toggle("cy_split", "Plot and table"),
            more = tagList(selectInput("cy_axis", "Year runs from", c("The water year start (Settings)" = "season", "1 January" = "calendar"), width = "100%"),
                           div(class = "btnrow", downloadButton("cy_png", "Export plot (PNG)"))),
            more_label = "Year start and export"),
          ovid_split("cy_split", width = "34%",
            ovid_focus(plotOutput("cy_plot", height = "560px")),
            tagList(h4("Summary by year"), tableOutput("cy_stats")))),
        tabPanel("Summaries",
          ovid_controls(
            tagAppendAttributes(selectizeInput("sm_sites", "Sites (blank = all)", choices = NULL, multiple = TRUE, width = "100%"), class = "d-wide"),
            selectInput("sm_param", "Value", param_choices[param_choices %in% SUMMARY_PARAMS], width = "100%"),
            radioButtons("sm_by", "By", c("Month" = "monthly", "Water year" = "water_year"), "water_year", inline = TRUE),
            more = tagList(checkboxInput("sm_complete", "Complete only", FALSE),
                           p(class = "dim", "From daily means (a day counts when it holds enough of its usual records). Water years start on the day set in Settings (Water year starts on; 1 October unless changed). A month or year is complete when it holds 90% of its days; incomplete ones are kept but marked."),
                           downloadButton("sm_dl", "Export this table (CSV)")),
            more_label = "Options and export"),
          DTOutput("sm_tbl")))),

    ovid_tool("Barometric", value = "Baro", icon = "gauge",
      page_head("Barometric", "Sites are grouped by the barologger that serves them. For each year, pick a primary barologger for every group and a secondary that fills the primary's gaps. The suggestion is the barologger with the best coverage of the group's deployments, then the nearest, then the one that agrees best with the others."),
      uiOutput("bo_empty"),
      div(class = "panel-x", fluidRow(column(3, selectInput("bo_year", "Processing year", choices = NULL, width = "100%"),
                                                p(class = "dim", style = "font-size:12px", "A processing year, and its baro groups, runs from one 15 September download sweep to the next, whatever the water year in Settings.")),
                                      column(9, uiOutput("bo_note")))),
      uiOutput("bo_groups"),
      div(class = "btnrow editor-only", actionButton("bo_save", "Save choices", class = "btn-primary", icon = icon("floppy-disk")),
          span(class = "dim", "Run the pipeline to apply.")),
      tabsetPanel(
        tabPanel("Barologgers over the year", ovid_focus(plotOutput("bo_plot", height = "380px")), ovid_focus(plotOutput("bo_diff", height = "300px"))),
        tabPanel("Baro stations across years",
          p(class = "dim", "A station is one place with a barometric record. Every barologger that was there is stitched into one series, so a record that runs for many years is compensated by whichever instrument was in place at the time. Where one barologger replaced another, the difference over their overlap is listed: a large step means the two disagree."),
          selectInput("bo_station", "Station", choices = NULL, width = "320px"), plotOutput("bo_station_plot", height = "360px"),
          h4("Where one barologger replaced another"), DTOutput("bo_seams"),
          h4("Which barologger belongs to which station"), p(class = "dim", "Give two serials the same ", code("station"), " to stitch them; give a serial its own name to keep it apart."), editUI("bstn"),
          h4("Other barometric records (fill-ins)"), p(class = "dim", "Optional: station pressure from another instrument (a Campbell climate station's export, say), used after the barologgers where neither chosen one has a reading (with fill-ins on). Any CSV: ",
            code("pressure_column"), " and ", code("units"), " (kPa, hPa, mbar, Pa, mmHg, inHg); ", code("time_column"), " blank: found by name; ", code("utc_offset_h"), " the zone of its times (blank: the time zone in Settings). With ",
            code("station_elevation_m"), " and ", code("reference_elevation_m"), " the pressure is brought to the barologgers' elevation (hypsometric equation); like every fill-in it is then shifted onto the primary's level."), editUI("xbaro")),
        tabPanel("Which site is in which group", p(class = "dim", "One row per site and year. Move a site by changing its group; add groups above by typing a new group name in the members table."), editUI("bmem")),
        tabPanel("How the suggestion was made", DTOutput("bo_scores")),
        tabPanel("Offset and drift",
          p(class = "dim", "Check a barologger against another one: a constant offset, a drift with time, or both. Name any barologger station or serial in ", code("barologger"), " and in ", code("reference"),
            " (for example Solinst_555 against HOBO_904, or against Solinst_556). ", code("method"), ": check, offset or offset_drift; ", code("apply"), ": yes to correct the barologger's readings on the next run (no = report only); ",
            code("from"), " / ", code("to"), ": an optional window (YYYY-MM-DD). Each check writes a report with the data, the method, the results, the decision and the R code used, under output/reports."),
          editUI("bcor"), h4("Sites each barologger check changes"), uiOutput("bo_check_sites"), h4("Results of the last run"), DTOutput("bo_checks")))),

    ovid_tool("Deployment history", value = "Deploy", icon = "timeline",
      page_head("Deployment history", "Where each serial was deployed, year by year, from the metadata workbook. A deployment runs from the logger's previous download visit to this year's. Set different dates, move a logger to another site, add a logger the workbook does not list, or give a hang length below; the workbook itself is never changed."),
      div(class = "scrollbox", plotOutput("dh_plot", height = "auto")),
      h4("Deployments"), div(class = "btnrow", radioButtons("dh_show", NULL, inline = TRUE, c("With data" = "data", "Every deployment in the workbook" = "all"))),
      DTOutput("dh_tbl"),
      h4("Corrections to the workbook"),
      p(class = "dim", "One row per change. ", code("serial"), " and ", code("year"), " pick the deployment (year blank = every year). ", code("site"), " moves it, or adds a deployment for a logger the workbook does not list that year. ",
        code("deployed"), " and ", code("removed"), " are date-times (YYYY-MM-DD HH:MM). ", code("T_ST_m"), " is the hang length in metres; ", code("T_ST_from_year"), " takes the value from another year's sheet. ",
        code("reference"), " is T or TOC. ", code("measured_to"), " is what the hang length was measured to: tip (the end of the logger, so the tip-to-sensor offset is added) or sensor (no offset); blank = the setting. ",
        "A row with a ", code("site"), " and no ", code("serial"), " applies to every logger at that site."), editUI("deps")),

    ovid_tool("Datum and dGPS", value = "Datum", icon = "ruler-vertical",
      page_head("Datum and dGPS", "Loggers hang from the T-coupler on the black iron pipe (the stable year-to-year datum) or, where there is none, from the top of the well casing. The survey of that point, the hang length T_ST (point to sensor tip) and the logger offset (tip to pressure sensor) place the sensor in space."),
      div(class = "formula", "sensor elevation   = reference elevation - T_ST + offset\nwater elevation    = sensor elevation + water above the sensor\ndepth to water     = T_ST - offset - water above the sensor          (below the T-coupler or casing)\ntape check         = T_ST - offset - T_water   (or TOC_water when T_ST was measured from the casing)"),
      tabsetPanel(
        tabPanel("Each deployment", DTOutput("dt_deps")),
        tabPanel("Survey points for each site", p(class = "dim", "Suggested links from survey names and distance are listed first; add a row below to fix a site to a survey point (", code("code"), " T, TOC or GS)."),
                 DTOutput("dt_links"), h4("Links set by hand"), editUI("gpsp")),
        tabPanel("Survey history", p(class = "dim", "Every survey of each site's reference points, as change from the first survey. A point that moves more than the survey's own error (", code("status"), ") is worth a look: a bumped pipe, a re-set casing or a bad fix. Select surveys and leave them out; the elevation then comes from the other surveys (choose nearest, latest or mean under Settings)."),
                 fluidRow(column(6, selectizeInput("gh_sites", "Sites", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "All sites"))),
                          column(3, checkboxInput("gh_moved", "Only points that moved", FALSE))),
                 plotOutput("gh_plot", height = "380px"), DTOutput("gh_tbl"),
                 div(class = "panel-x editor-only", fluidRow(column(6, textInput("gh_reason", "Reason", width = "100%")), column(3, textInput("gh_author", "Initials", width = "100%"))),
                     div(class = "btnrow", actionButton("gh_exclude", "Leave out the selected surveys", class = "btn-danger"))),
                 h4("Surveys left out"), editUI("gex")),
        tabPanel("Survey points", DTOutput("dt_gps")),
        tabPanel("Elevations typed by hand", p(class = "dim", "For sites surveyed another way. ", code("code"), " T, TOC or GS; ", code("elevation_m"), " in metres; ", code("date"), " of the survey. Optional: ", code("height_type"), " ellipsoidal for an ellipsoidal height h, with ", code("geoid_N_m"), " to turn it into an elevation H = h \u2212 N (else it is not mixed with elevations); ", code("frame"), " (NAD83(CSRS) v8 ...), ", code("epoch"), " and ", code("geoid_model"), " (CGG2013a ...) are kept with the value."), editUI("datm")),
        tabPanel("Logger offsets", p(class = "dim", "Distance from the logger tip up to the pressure sensor, in metres. Matched on ", code("serial"), " first, then on ", code("model"),
          ", a pattern tried against the model name in the files (first row first; | separates alternatives). A blank ", code("offset_m"), " is skipped. ",
          "It is added only where the hang length was measured to the tip (", code("measured_to"), " on Deployment history, or Settings); set it to 0 to leave it out. ",
          code("source"), " says where a value came from; the seeded rows are the makers' specifications."),
          div(class = "panel-x editor-only",
            fluidRow(column(3, radioButtons("of_for", "Set the offset for", c("A logger model" = "model", "One logger (serial)" = "serial"), "model")),
                     column(4, selectizeInput("of_target", "Model or serial", choices = NULL, width = "100%", options = list(create = TRUE, placeholder = "pick or type"))),
                     column(5, selectInput("of_known", "Offset", choices = c("Manual measurement" = "manual"), width = "100%"))),
            fluidRow(column(3, conditionalPanel("input.of_known == 'manual'", numericInput("of_cm", "Measured tip to sensor (cm)", NA, min = 0, step = 0.05, width = "100%"))),
                     column(4, textInput("of_note", "Note (how it was measured)", width = "100%")), column(2, textInput("of_author", "Initials", width = "100%")),
                     column(3, div(style = "margin-top:25px", actionButton("of_set", "Set offset", class = "btn-primary", icon = icon("ruler"))))),
            p(class = "dim", "Pick a known offset from the list, or Manual measurement and type the distance from the tip of the logger to its pressure sensor (the mark or line on the housing), in cm. ",
              "Setting it again for the same model or serial replaces the row; a new row goes to the top so it wins over broader patterns.")),
          editUI("offs")))),

    ovid_tool("Field visits", value = "Visits", icon = "person-hiking",
      page_head("Field visits", "Every download and visit in the workbook with its manual measurements (converted from cm to m), for one site."),
      selectInput("fv_site", "Site", choices = NULL, width = "360px"), DTOutput("fv_tbl"),
      h4("Manual measurements"),
      p(class = "dim", "Readings taken by hand: a tape, a handheld thermometer or conductivity meter, a survey of the water surface. They are reference points only: shown on Plot and explore beside the logger, with the difference, and never used to change the data. ",
        code("time"), " as YYYY-MM-DD HH:MM in the project's time zone; ", code("parameter"), ": depth_m (water above the sensor), dtw_m (water below the reference point), elev_m, temp_c or spc_uscm; ", code("value"), " in m, \u00b0C or \u00b5S/cm."),
      editUI("meas"),
      h4("Tape against logger (last run)"),
      p(class = "dim", "Drift is usually 1 to 3 cm a year, so a larger steady difference between the tape and the logger more likely means a metadata error: the hang length (T_ST), the logger offset or the reference point. Nothing is changed. ",
        "To adjust, change ", code("T_ST_m"), " on Deployment history, or the offset on Datum and dGPS > Logger offsets, and run again. To keep the values as they are, select the rows and press Keep: it adds a ", code("drift_keep"), " row to Corrections over a period (Quality rules) and the warning goes away on the next run."),
      div(class = "btnrow editor-only", actionButton("fv_keep", "Keep selected as they are", icon = icon("check")), checkboxInput("fv_tape_all", "Show deployments within the limit too", FALSE)),
      DTOutput("fv_tape"),
      h4("Result of the last run"), DTOutput("fv_drift")),

    ovid_tool("Hydrology and uncertainty", value = "Hydro", icon = "water",
      page_head("Hydrology and uncertainty", "What the run works out from the compensated records, beside them and changing none of them: how certain each deployment is, whether a well answers the air pressure, whether a casing moved, the water table against the ground, and gradients and recharge where you give the wells and the specific yield."),
      tabsetPanel(
        tabPanel("Uncertainty", p(class = "dim", "The standard uncertainty (1 sigma) of each deployment: the logger's stated accuracy, the barometric record (a fill-in from another station counts for more), the water density, the spread of the tape checks (which holds the hang length, offset and tape) and the survey of the reference point, added in quadrature. The errors are systematic over a deployment, so a daily or yearly mean keeps them (", code("sigma_m"), " in the summaries)."),
                 DTOutput("hy_unc"), h4("Logger accuracy"), p(class = "dim", code("pattern"), " is tried against the serial, then the model (first row first); ", code("sigma_m"), " in metres of water. The seeded rows are typical values from the makers' sheets: check your models."), editUI("acc")),
        tabPanel("Barometric efficiency", p(class = "dim", "A well in the water table does not answer the air pressure once compensated; one screened in a confined layer does, at once or with a delay. Hourly changes of the depth are regressed on the changes of air pressure at lags up to a day (Rasmussen and Crawford 1997): ", code("be_lag0"), " is the immediate response, ", code("be_cumulative"), " the response after a day."), DTOutput("hy_be")),
        tabPanel("Casing movement", p(class = "dim", "The casing's height above the ground (TOC_veg) at each visit against the visit before. A change beyond the limit in Settings means the casing moved against the ground: frost jacking, or the ground sank or rose around it. Hang lengths from the casing and surveys of its top are then out of date."), DTOutput("hy_casing")),
        tabPanel("Hydroperiod", p(class = "dim", "Per site and water year: days with the daily water table at or above the ground, the longest run of them, and the mean water table against the ground. The water table against the ground comes from the T-coupler to vegetation height of the visit, or from a surveyed ground point (GS)."), DTOutput("hy_hp")),
        tabPanel("Gradients", p(class = "dim", "The difference of the daily water elevations of two wells over the distance between them (positive: from a to b), with its uncertainty. A nest of piezometers gives the vertical gradient the same way (distance = the difference of the screen depths)."),
                 DTOutput("hy_grad"), h4("Pairs of wells"), editUI("pairs")),
        tabPanel("Recharge", p(class = "dim", "Water-table fluctuation (Healy and Cook 2002), in its simplest form: specific yield times the sum of the daily rises, per water year. A first estimate: peat's specific yield falls with depth, and rises from lateral inflow count too. ", code("site"), " * gives every site the value."),
                 DTOutput("hy_rch"), h4("Specific yield"), editUI("sy")))),

    ovid_tool("Audit trail", value = "Audit", icon = "clipboard-check",
      page_head("Audit trail", "Nothing leaves the data without a line here. Record counts are reconciled for every logger at the end of each run."),
      uiOutput("au_cards"),
      h4("1. What was done, and why"), p(class = "dim", "Click a line to see what it means and where it happened."), DTOutput("au_rules"), uiOutput("au_explain"),
      h4("2. Where it happened"), DTOutput("au_where"),
      h4("3. Reconciliation by logger"), DTOutput("au_recon"),
      h4("4. Every raw file"), p(class = "dim", "Each file found, its checksum (md5), how many readings it held, how many reached the output, where they went and why any were dropped. ", code("reconciles"), " checks read = in output + dropped for every used file."),
      div(class = "btnrow", radioButtons("au_fshow", NULL, inline = TRUE, c("Used" = "used", "Not used" = "unused", "Does not reconcile" = "bad", "All" = "all")), span(class = "push"), downloadButton("au_fdl", "Export file audit (CSV)")),
      DTOutput("au_files")),

    "Report",
    ovid_tool("Reports and export", value = "Export", icon = "file-export",
      page_head("Export", "Compensated, quality-controlled data for the sites picked, in one of four forms: the package (one zip that can be used without the app: a tidy CSV per deployment with flag columns, the deployment summary, the tape checks, the audit trail, the reports and a readme), one CSV, one file per site, or a report."),
      div(class = "panel-x",
          fluidRow(column(6, selectizeInput("cd_sites", "Sites", choices = NULL, multiple = TRUE, width = "100%", options = list(placeholder = "Pick one or more (blank = all)"))),
                   column(6, selectizeInput("cd_values", "Values", choices = param_choices[c(1:3, 11, 7:9, 4:6)], selected = c("depth_m", "elev_m", "temp_c"), multiple = TRUE, width = "100%"))),
          fluidRow(column(3, radioButtons("cd_res", "Time step", c("Every reading" = "raw", "Hourly mean" = "hour", "Daily mean" = "day"), inline = FALSE)),
                   column(3, radioButtons("cd_layout", "Layout", c("Long (one row per site and time)" = "long", "Wide (a column per site)" = "wide"))),
                   column(4, dateRangeInput("cd_dates", "Period (set to the whole record of the sites picked)")),
                   column(2, checkboxInput("cd_flags", "Quality flags", TRUE), radioButtons("cd_scheme", NULL, c("WMO codes 0 to 7" = "wmo", "Letters S, R, M" = "ovid"), "wmo"),
                          radioButtons("cd_versions", "Drift corrected values", c("Both versions" = "both", "Logger's values only" = "original", "Corrected values only" = "corrected"), "both"),
                          checkboxInput("cd_nc", "ZIP: NetCDF too (CF-1.10)", FALSE))),
          radioButtons("xp_fmt", "Format", c("ZIP package" = "package", "One CSV" = "csv", "One file per site (ZIP)" = "sites", "Report" = "report"), "package", inline = TRUE),
          conditionalPanel("input.xp_fmt == 'package'", checkboxGroupInput("xp_rep", "Reports in the package (run report and one per site)", REPORT_FORMATS, c("html", "pdf"), inline = TRUE),
