                           p(class = "dim", "One site picked: that site across every season (water level, elevation and temperature by season, tape checks, removals). Otherwise the run report (files, deployments, tape checks, barometric seams, removals, problems).")),
          div(class = "btnrow", actionLink("cd_all", "Select all sites"), textOutput("cd_count", inline = TRUE), span(class = "push"), downloadButton("xp_dl", "Export", class = "btn-primary"))),
      report_options_ui("rpo", WLR_REPORT_SECTIONS),
      div(class = "explain", tags$b("Flag columns"), tags$br(), "A column ending in ", code("_flag"), " sits beside each value: ", tags$b("S"), " suspect (kept), ", tags$b("R"), " removed by a quality rule, ", tags$b("M"), " missing. Removed values are blank. Time stamps are in the time zone set in Settings, without daylight saving."),
      h4("Approvals"), p(class = "dim", "A site's record is approved up to a date after a review, and provisional after it (as at the USGS and the Water Survey of Canada). Exports carry the state of every value. ", code("site"), " * approves every site to that date."), editUI("appr"),
      h4("Deployment summary"), DTOutput("xp_sum")),

    "Set up",
