               column(7, div(class = "panel-x editor-only", h3("Import"), p(class = "dim", "A zip exported from this app, a single set-up CSV (recognised by its columns), or an .xlsx with one sheet per table. Nothing changes until you apply it; the current tables are backed up first."),
