                             DTOutput("cf_preview"), div(class = "btnrow", actionButton("cf_apply", "Apply the import", class = "btn-primary"), checkboxInput("cf_settings", "Also apply its settings (folders, Settings and the Automatic corrections switches)", FALSE)))))),
