          radioButtons("solinst_altitude", "Solinst altitude setting (Levelogger / Barologger Gold and Junior add altitude/826 m of water to every reading when programmed with an altitude)",
                     c("Take it off the readings, from each file's header (default)" = "undo", "Use the readings as stored (original, uncorrected)" = "keep"), SETTINGS$solinst_altitude %||% "undo"),
          radioButtons("hang_measured_to", "Hang lengths (T_ST) are measured to, unless a deployment says otherwise", c("The tip of the logger (default)" = "tip", "The pressure sensor" = "sensor"), SETTINGS$hang_measured_to %||% "tip"),
          checkboxInput("add_sensor_offset", "Add tip-to-sensor offset", isTRUE(SETTINGS$add_sensor_offset)),
          p(class = "dim", "Adds the logger's tip-to-sensor distance (Datum and dGPS, Logger offsets) where the hang length was measured to the tip."),
          radioButtons("density_mode", "Water density", c("Fixed" = "fixed", "From the logger's water temperature (Tanaka 2001)" = "temperature"), SETTINGS$density_mode))),
        column(6, div(class = "panel-x", h3("Checks"),
          numericInput("service_window_h", "Flag readings within this many hours of a visit or download", SETTINGS$service_window_h, step = 0.5, width = "100%"),
          numericInput("out_of_water_m", "Out of the water below (m of water above the sensor): flagged anywhere", SETTINGS$out_of_water_m, step = 0.01, width = "100%"),
          div(class = "d-air", tags$style(".d-air:has(#air_same_as_oow:checked) .d-air-alt{opacity:.45;pointer-events:none}"),   # the own limit applies only with the switch off
            checkboxInput("air_same_as_oow", "In-air detection uses the out-of-water limit", !isFALSE(SETTINGS$air_same_as_oow)),
            p(class = "dim", "Loggers often record before being lowered into the well or after removal. Readings at the start or end of a deployment with less water above the sensor than the limit are flagged as in air."),
            div(class = "d-air-alt", numericInput("air_threshold_cm", "Otherwise, in-air limit (cm of water above the sensor)", SETTINGS$air_threshold_cm, step = 0.5, width = "100%"))),
          radioButtons("drift_correction", "Drift between tape checks", c("Off (default)" = "off", "Apply the offsets from the tape checks" = "apply"), if (identical(SETTINGS$drift_correction, "apply")) "apply" else "off"),
          checkboxInput("baro_fill", "Fill baro gaps from other stations when the primary and secondary are both missing (shifted and flagged)", isTRUE(SETTINGS$baro_fill)),
          checkboxInput("auto_trim_air", "Trim readings in the air at the start and end of each deployment (otherwise flag them)", isTRUE(SETTINGS$auto_trim_air)),
          numericInput("air_max_hours", "Longest run at a deployment's start or end treated as in the air (hours)", SETTINGS$air_max_hours, step = 1, width = "100%"),
          radioButtons("dgps_pick", "When a reference point has several surveys, use", c("The survey nearest the deployment" = "nearest", "The latest survey" = "latest", "The mean of all surveys" = "mean",
                     "Follow the surveys in time (interpolated; for subsiding ground)" = "interpolate"), SETTINGS$dgps_pick %||% "nearest"),
          textInput("water_year_start", "Water year starts on (month-day; 10-01 = 1 October, the hydrological year). Used by summaries, hydroperiod, recharge and the year-by-year plot",
                    SETTINGS$water_year_start %||% "10-01", width = "100%")),
          div(class = "explain", "Pressure in kPa \u2192 water above the sensor: h = (P", tags$sub("water"), " \u2212 P", tags$sub("baro"), ") \u00d7 1000 / (\u03c1 g). Solinst LEVEL is pressure written as metres of water, turned into kPa with the factor under Advanced first."))),
      tags$details(class = "d-drawer", tags$summary("Advanced"), p(class = "dim", "Physical constants and expert thresholds. The defaults suit most projects; change them only with a reason."),
        fluidRow(column(6,
          numericInput("solinst_kpa_per_m", "Solinst: kPa per metre of LEVEL", SETTINGS$solinst_kpa_per_m, step = 0.0001, width = "100%"),
          numericInput("fixed_density", "Fixed density (kg/m\u00b3)", SETTINGS$fixed_density, step = 0.1, width = "100%"),
          numericInput("gravity", "Gravity (m/s\u00b2)", SETTINGS$gravity, step = 0.00001, width = "100%"),
          numericInput("ec_alpha", "Conductivity temperature coefficient (per \u00b0C)", SETTINGS$ec_alpha, step = 0.0001, width = "100%"),
          numericInput("baro_max_gap_h", "Interpolate barometric pressure across gaps up to (hours)", SETTINGS$baro_max_gap_h, step = 0.5, width = "100%"),
          numericInput("check_window_h", "Compare logger with tape over the hours before a visit", SETTINGS$check_window_h, step = 0.5, width = "100%")),
                 column(6,
          numericInput("sigma_baro_m", "Uncertainty of compensation with a barologger at the site (m of water, 1 sigma)", SETTINGS$sigma_baro_m, step = 0.001, width = "100%"),
          numericInput("sigma_fill_m", "... with a fill-in from another station (m)", SETTINGS$sigma_fill_m, step = 0.005, width = "100%"),
          numericInput("sigma_tape_m", "... of a tape check, with fewer than two to take the spread from (m)", SETTINGS$sigma_tape_m, step = 0.005, width = "100%"),
          numericInput("sigma_survey_m", "... of a survey that gives no rms (m)", SETTINGS$sigma_survey_m, step = 0.005, width = "100%"),
          numericInput("be_flag", "Barometric efficiency flag: list deployments with BE above", SETTINGS$be_flag, step = 0.05, width = "100%"),
          p(class = "dim", "BE: the fall in compensated water level per rise in air pressure (both in m of water), by regression deconvolution (Rasmussen and Crawford 1997). A lasting BE above the limit indicates incomplete compensation or a confined layer; listed in audit/barometric_efficiency.csv."),
          numericInput("casing_tol_m", "Report a casing whose height above the ground changes between visits by more than (m)", SETTINGS$casing_tol_m, step = 0.005, width = "100%"))),
        h4("Tape drift correction"), p(class = "dim", "With drift between tape checks applied (Checks), the logger level is shifted to match the tape. With two or more checks the offset is interpolated linearly between them."),
        fluidRow(column(4, numericInput("drift_min_m", "Apply when the largest logger\u2013tape difference is at least (m)", SETTINGS$drift_min_m, step = 0.005, width = "100%")),
