# The Standard view as the set-up flow (core 1.2): the site dashboard first, then five stages and nine shared steps with
# WLR's own pages beside them, and the rest under More. The Workbench shows the same pages in its own frame (sources = FALSE:
# the folders are under its Import data).
wlr_flow_pages <- function(sources = TRUE) {
  pg <- Filter(function(x) inherits(x, "ovid_tool"), std_pages(sources)); by <- setNames(pg, vapply(pg, `[[`, "", "value"))
  step <- function(v, n = NULL, title = NULL, icon = NULL) { x <- ovid_retitle(by[[v]], n, title); if (!is.null(x) && !is.null(icon)) x$icon <- icon; x }
  nxt <- function(label, go) ovid_next(paste("Next:", label), go)
  E <- !VIEWER
  list(
    ovid_tool("Site", value = "Site", icon = "water",
      div(class = "d-head d-site-head", h2(class = "d-title", uiOutput("site_title", inline = TRUE)), uiOutput("site_chips", inline = TRUE),
          div(class = "d-head-actions", actionButton("site_prev", "\u2039", title = "The site before"), div(class = "jump", selectInput("site_pick", NULL, choices = NULL, width = "220px")),
              actionButton("site_next", "\u203a", title = "The next site"), tags$a(class = "btn btn-default", href = "#", `data-ovid-go` = "Export", icon("file-export"), " Report"),
              downloadButton("site_dl", "Data"))),
      uiOutput("site_empty"),
      div(class = "d-dash", div(class = "d-kpis", uiOutput("site_kpis")), div(class = "d-cardx d-dash-plot", ts_viewbar(precip = TRUE), ts_view("site_plot", 230))),
      div(class = "d-cardx", div(class = "d-head", h3("Deployments at this site"),
          div(class = "d-head-actions", if (E) tags$a(class = "btn btn-default btn-sm", href = "#", `data-ovid-go` = "Needs", "Add from loggers without a deployment"),
              if (E) tags$a(class = "btn btn-default btn-sm", href = "#", `data-ovid-go` = "Metadata", "Edit"),
              downloadButton("site_deps_dl", "Export", class = "btn-sm"))),
          uiOutput("site_deps"))),
    ovid_stage(1, "Bring in"),
    if (E) ovid_tool("Project", value = "Project", icon = "folder-tree", n = 1,
      ovid_step_head(1, "Project", "Where the raw data are read from and where this project keeps its set-up tables and outputs. Raw files are never changed."),
      if (sources) std_folders() else p(class = "dim", "The folders are under Import data in the Workbench."),
      div(class = "d-cardx", h3("Precipitation (optional)"),
          p(class = "dim", "A CSV with a time and millimetres, from a rain gauge or a climate station. It is drawn as bars under the plots and changes no data."),
          textInput("precip_file", NULL, SETTINGS$precip_file %||% "", width = "100%", placeholder = "path to a .csv"), uiOutput("precip_check")),
      nxt("Bring in files", "Files")),
    if (E) step("Files", 2, "Bring in files", "file-import"),
    ovid_stage(2, "Organize"),
    if (E) step("Metadata", 3, "Loggers and deployments"),
    if (E) ovid_tool("Needs you", value = "Needs", icon = "circle-question", n = 4,
      ovid_step_head(4, "Needs you", "Only a match by dates is assigned on its own. Everything else (a year, a name in the files, a logger's only deployment) is a suggestion here, accepted with one click. Below them, what the last run flagged and found, each decided here."),
      deploy_check_ui("depcheck"), div(class = "d-cardx", h3("What the last run found"), review_list_ui("rl")), nxt("Sites: rename, what shows", "Shown")),
    if (E) ovid_tool("Sites: rename, what shows", value = "Shown", icon = "eye", n = 5,
      ovid_step_head(5, "Sites: rename, what shows", "Rename a site once and it is renamed in every set-up table (with a preview and Undo). Choose which sites show on the strip, Home and Needs you (they are still processed and exported)."),
      div(class = "d-cardx", rename_ui("ren")), div(class = "d-cardx", h3("What shows"), display_ui("disp", "site")), nxt("Clocks", "Clock")),
    step("Deploy", NULL, "Deployment history"),
    ovid_stage(3, "Correct"),
    if (E) step("Clock", NULL, "Clocks"),
    step("Baro", NULL, "Barometric compensation"),
    step("Datum", NULL, "Datum and offsets"),
    step("Visits", NULL, "Manual levels and drift", "pen"),
    if (E) step("QC", NULL, "Quality rules"),
    if (E) ovid_tool("Automatic corrections", value = "Corrections", icon = "wand-magic-sparkles", n = 6,
      ovid_step_head(6, "Automatic corrections", "Corrections every run makes on its own, each with a switch. They are on by default."),
      div(class = "d-cardx", corrections_ui("corr")), nxt("Report", "Export")),
    ovid_stage(4, "Report"),
    step("Export", 7, "Report"),
    "More",
    step("Home", NULL, "Overview"), step("Explore"), step("Hydro"), step("Audit"), step("Preflight"), step("Config"),
    step("Settings"))
}

ui <- do.call(ovid_page, c(list("WLR", NORD, tokens = WLR_TOKENS, css = std_css(), head = std_head(),
  status = uiOutput("runstate", inline = TRUE),
  layout = "icons", project = if (!VIEWER) projects_switch_ui("proj"), context = uiOutput("flow_ctx", inline = TRUE), aside = uiOutput("flow_info"),
  actions = tagList(applied_ui("applied"), if (!VIEWER) unsaved_ui("uns"),
                    if (VIEWER) span(class = "modebadge", "Viewer") else actionButton("run", "Run pipeline", class = "btn-primary", icon = icon("play"))),
  help = if (file.exists(file.path(APP_DIR, "docs", "WLR_reference_guide.html"))) "docs/WLR_reference_guide.html",
  settings = "Settings"), c(wlr_flow_pages(), list(convert_tool(), reference_tool("WLR")))))
